package com.crm.invoice;
import com.crm.invoice.service.*;import com.crm.invoice.controller.PersonalInvoiceController;import com.crm.invoice.client.PersonalCustomerClient;import com.crm.invoice.repository.*;import com.crm.invoice.entity.Invoice;import com.crm.security.AuthenticatedUserPrincipal;import org.junit.jupiter.api.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.mock.web.MockHttpServletRequest;import org.springframework.test.util.ReflectionTestUtils;import java.util.*;import java.math.BigDecimal;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class InvoiceFrozenOwnershipTest {
 InvoiceRepository invoices=mock(InvoiceRepository.class);InvoicePaymentRepository payments=mock(InvoicePaymentRepository.class);PersonalCustomerClient customers=mock(PersonalCustomerClient.class);InvoicePresentationService documents=mock(InvoicePresentationService.class);PersonalInvoiceController controller;UsernamePasswordAuthenticationToken auth;
 @BeforeEach void setup(){var roles=List.of(new SimpleGrantedAuthority("ROLE_CLIENT"));auth=new UsernamePasswordAuthenticationToken(new AuthenticatedUserPrincipal(42,"client",roles),null,roles);controller=new PersonalInvoiceController(new PersonalInvoiceService(invoices,customers,payments));ReflectionTestUtils.setField(controller,"documents",documents);when(customers.own("Bearer synthetic")).thenReturn("101");}
 @Test void ownerMayReadAnArchivedFrozenDocument(){var invoice=new Invoice();invoice.setId(7L);invoice.setCustomerId("101");invoice.setArchived(true);invoice.setIssued(true);invoice.setTotalAmount(new BigDecimal("30.85"));when(invoices.findByIdAndCustomerId(7L,"101")).thenReturn(Optional.of(invoice));byte[] bytes="%PDF-synthetic".getBytes();when(documents.snapshot(7L)).thenReturn(bytes);var response=controller.pdf(auth,"Bearer synthetic","7",new MockHttpServletRequest());assertArrayEquals(bytes,response.getBody());assertEquals("no-store",response.getHeaders().getCacheControl());var order=inOrder(invoices,documents);order.verify(invoices).findByIdAndCustomerId(7L,"101");order.verify(documents).snapshot(7L);}
 @Test void anotherClientCannotReachTheFrozenDocumentStore(){when(invoices.findByIdAndCustomerId(8L,"101")).thenReturn(Optional.empty());assertThrows(org.springframework.web.server.ResponseStatusException.class,()->controller.pdf(auth,"Bearer synthetic","8",new MockHttpServletRequest()));verifyNoInteractions(documents);}
 @Test void targetParameterIsRejectedBeforeAssociationOrDocumentRead(){var request=new MockHttpServletRequest();request.setParameter("customerId","102");assertThrows(IllegalArgumentException.class,()->controller.pdf(auth,"Bearer synthetic","7",request));verifyNoInteractions(customers,invoices,documents);}
}
